#include <bits/stdc++.h>
using namespace std;
using U=uint64_t;
int main(){
 vector<array<int,4>> vs; array<int,4>a={0,1,2,3};do{vs.push_back(a);}while(next_permutation(a.begin(),a.end()));
 map<array<int,4>,int> id;for(int i=0;i<24;++i)id[vs[i]]=i;
 vector<pair<int,int>> es;for(int i=0;i<24;++i)for(int j=0;j<3;++j){a=vs[i];swap(a[j],a[j+1]);int k=id[a];if(i<k)es.emplace_back(i,k);}sort(es.begin(),es.end());
 cout<<"V="<<vs.size()<<" E="<<es.size()<<"\n";
 array<uint32_t,24> closed;closed.fill(0);for(int i=0;i<24;++i)closed[i]=1u<<i;for(auto [x,y]:es){closed[x]|=1u<<y;closed[y]|=1u<<x;}
 vector<U> dsets;unsigned long long small=0;
 auto comb=[&](int k,auto cb){if(k==0){cb(0ull);return;}U mask=(1ull<<k)-1;const U MAX=1ull<<24;do{cb(mask);U c=mask&-mask; U r=mask+c;mask=(((r^mask)>>2)/c)|r;}while(mask<MAX);};
 for(int k=0;k<=8;k++){unsigned long long count=0;comb(k,[&](U d){int j=0;for(;j<24;j++)if(!(closed[j]&d))break;if(j==24){count++;if(k==8)dsets.push_back(d);}});cout<<"dominating_size_"<<k<<"="<<count<<"\n";}
 vector<vector<U>> blocks;blocks.reserve(dsets.size());
 for(U d:dsets){vector<U> qs;for(int v=0;v<24;++v)if(!(d&(1ull<<v))){U q=0;for(int e=0;e<36;e++){auto [x,y]=es[e];if((x==v&&((d>>y)&1))||(y==v&&((d>>x)&1)))q|=1ull<<e;}assert(q);qs.push_back(q);}blocks.push_back(qs);}
 cout<<"8-minimum sets="<<dsets.size()<<"\n";
 vector<U> winners;vector<int> hist(7); unsigned long long total=0, cut=0, c4=0;
 // edge combinations as Gosper with boundary 36
 auto enum_edges=[&](int k,auto cb){if(k==0){cb(0ull);return;}U mask=(1ull<<k)-1;const U MAX=1ull<<36;do{cb(mask);U c=mask&-mask;U r=mask+c;mask=(((r^mask)>>2)/c)|r;}while(mask<MAX);};
 for(int k=0;k<=5;k++){unsigned long long examined=0,success=0;enum_edges(k,[&](U F){examined++;bool surviving=false;for(auto &qs:blocks){bool Dsurvive=true;for(U q:qs)if((q&F)==q){Dsurvive=false;break;}if(Dsurvive){surviving=true;break;}}if(!surviving){success++;if(k==5)winners.push_back(F);}});cout<<"k="<<k<<" examined="<<examined<<" bondage="<<success<<"\n";}
 cout<<"five_winners="<<winners.size()<<"\n";
 // enumerate Aut group generated by value relabelings and position reversal
 vector<array<int,36>> autos;
 array<int,4> val={0,1,2,3};do{for(int rev=0;rev<2;rev++){array<int,24> pp;for(int v=0;v<24;v++){a=vs[v];if(rev)reverse(a.begin(),a.end());for(auto &z:a)z=val[z];pp[v]=id.at(a);}array<int,36> emap;for(int e=0;e<36;e++){auto [x,y]=es[e];x=pp[x],y=pp[y];if(x>y)swap(x,y);auto it=lower_bound(es.begin(),es.end(),pair<int,int>{x,y});assert(it!=es.end()&&(*it==pair<int,int>(x,y)));emap[e]=it-es.begin();}autos.push_back(emap);}}while(next_permutation(val.begin(),val.end()));
 map<U,int> orbit;for(U w:winners){U rep=~0ull;for(auto const& perm:autos){U t=0;for(int e=0;e<36;e++)if((w>>e)&1)t|=1ull<<perm[e];rep=min(rep,t);}orbit[rep]++;}
 cout<<"num_orbits="<<orbit.size()<<" sizes=";for(auto [rep,sz]:orbit)cout<<sz<<",";cout<<"\n";
 for(auto [rep,sz]:orbit){cout<<"representative orbit "<<sz<<": ";for(int e=0;e<36;e++)if((rep>>e)&1)cout<<"("<<es[e].first<<","<<es[e].second<<") ";cout<<"\n";}
}
